import { host } from "host";

async function main() {
  const status = await host.server.status();
  const { x, y, z } = status.demoLocation;

  const [broadcastRes, spawn1, spawn2, spawn3, msgRes] = await Promise.all([
    host.chat.broadcast("Warning: Zombies incoming nearby!"),
    host.world.spawnEntity({ type: "ZOMBIE", x: x + 1, y, z }),
    host.world.spawnEntity({ type: "ZOMBIE", x: x - 1, y, z }),
    host.world.spawnEntity({ type: "ZOMBIE", x, y, z: z + 1 }),
    host.player.sendMessage("GoldennBullet", "3 zombies spawned at demo location.").catch((err) => ({ accepted: false, error: String(err) }))
  ]);

  console.log(JSON.stringify({
    serverStatus: status,
    broadcast: broadcastRes,
    spawns: [spawn1, spawn2, spawn3],
    playerNotification: msgRes
  }));
}

await main();

